INSERT INTO walk_acts (fence_id, companion_id, joke_id, act_index, version_id, content, label)
VALUES
('gf-01', 'sharp-elder', 'elder-a', 0, 'gf-01-elder-a-l1', '看见门楣上那俩字儿没？“恭王府”。别被这名字骗了，这宅子跟“恭”字儿半毛钱关系没有。它的第一任主人，叫和珅。', NULL),
('gf-01', 'sharp-elder', 'elder-a', 1, 'gf-01-elder-a-l2', '和珅抄家那会儿，从他家抄出来的白银，折合现在的人民币——你站稳了——大概三千个亿。什么概念？当时清政府一年的财政收入才七千万两，他家顶国库十五年。嘉庆皇帝接了个大礼包。', '和珅有多富'),
('gf-01', 'sharp-elder', 'elder-a', 2, 'gf-01-elder-a-l3', '和珅的精明，全藏在“不露”二字上。你抬头看这大门，表面上就是个普通的一品大员府邸，没逾制。但好东西全藏在里头，比如那后罩楼的窗户——每一扇形状都不一样，里头全是他放宝贝的库房。他不用账本，看一眼窗户形状就知道哪个屋放了什么。这才是贪污的艺术。', NULL),
('gf-01', 'sharp-elder', 'elder-b', 0, 'gf-01-elder-b-l1', '看见门楣上那俩字儿没？“恭王府”。别被这名字骗了，这宅子跟“恭”字儿半毛钱关系没有。它的第一任主人，叫和珅。', NULL),
('gf-01', 'sharp-elder', 'elder-b', 1, 'gf-01-elder-b-l2', '这宅子的产权证，比宫斗剧还精彩。先是和珅的，抄家后赐给了庆郡王永璘——这位爷当年跟着嘉庆抄和珅，开口就说“金银归你，宅子归我”。结果后来辗转到了恭亲王奕䜣手里。从贪官到郡王再到亲王，谁都没住安稳。', '豪宅换了三个主人'),
('gf-01', 'sharp-elder', 'elder-b', 2, 'gf-01-elder-b-l3', '奕䜣接手时，这宅子已经年久失修。他花了大把银子翻新，建成了京城最气派的王府。可讽刺的是，他是道光最喜欢的儿子，两次跟皇位擦肩而过，一辈子活在慈禧的猜忌里。王府越修越豪华，他心里的窟窿越来越大。这哪儿是什么府邸啊，这是中国近代史的候诊室。', NULL),
('gf-01', 'su-dongpo', 'su-a', 0, 'gf-01-su-a-l1', '哈哈，这扇门开合之间，送走了多少自认能掌控命运的人。和珅当年每日进进出出，可曾想过，门外的嘉庆已在磨刀？', NULL),
('gf-01', 'su-dongpo', 'su-a', 1, 'gf-01-su-a-l2', '我在汴京做官时，见过太多人把宅子修得比庙还大。和珅以为高墙能挡住一切，却不知墙越高，倒时砸出的声响越骇人。皇上的赏赐，今天叫恩宠，明天就叫罪证——我当年被贬黄州，罪名不过是几首诗。', '权力的无常'),
('gf-01', 'su-dongpo', 'su-a', 2, 'gf-01-su-a-l3', '乌台诗案那年，我被关了103天。审讯我的官员，后来也被审讯；抄我诗的那位御史，后来也被抄家。风水轮流转这件事，我在宋朝转了好几圈。和珅和我在时间的两头，踩进的是同一条河。所以我一直说：广厦万间，夜眠仅需六尺。这不是酸葡萄，是被打过的教训。', NULL),
('gf-01', 'su-dongpo', 'su-b', 0, 'gf-01-su-b-l1', '哈哈，这扇门开合之间，送走了多少自认能掌控命运的人。和珅当年每日进进出出，可曾想过，门外的嘉庆已在磨刀？', NULL),
('gf-01', 'su-dongpo', 'su-b', 1, 'gf-01-su-b-l2', '不过话说回来，我若是和珅，可能也会造一座这样的宅子。不是贪，是爱。一个人对空间之美的追求，有时候就是天生的——我当年在黄州赤壁，穷得叮当响，还非要在崖边搭个亭子看江。这恭王府的妙处，且随我进去看看。', '园林之趣'),
('gf-01', 'su-dongpo', 'su-b', 2, 'gf-01-su-b-l3', '我在徐州做太守时，修了一座黄楼，不为别的，就为看黄河水天一色。后世说我是“水利工程师”，但我只是觉得：人一生，得有一处看水的地方。和珅这后花园引了御河的水，他大概也这么想。只不过他用了皇家的水源，我用了自己的俸禄。境界高下，立判。', NULL),
('gf-02', 'sharp-elder', 'elder-a', 0, 'gf-02-elder-a-l1', '银安殿，王府的正殿。听着挺唬人吧？其实就是和珅家的大客厅。看见那七开间的大气派没？比紫禁城是小多了，但在王爷堆儿里，这是顶配。', NULL),
('gf-02', 'sharp-elder', 'elder-a', 1, 'gf-02-elder-a-l2', '你仔细数这开间，七间。按大清会典，亲王府才七间，郡王只能五间。和珅当年是一等忠襄公，理论上也就公爵府规制，可你看这架势——他从一开始就没打算按规矩来。乾隆是真不知道，还是装不知道？我估摸着，是睁一只眼闭一只眼。', '逾制的秘密'),
('gf-02', 'sharp-elder', 'elder-a', 2, 'gf-02-elder-a-l3', '乾隆到了晚年，身边没几个可信的人。和珅给他办的事儿，从敛财到处理棘手政务，利索得很。所以和珅逾制这事儿，在乾隆那儿不叫“贪”，叫“给能臣的弹性空间”。等到嘉庆上来，同样的行为就叫“大逆不道”。一个毛病，两个皇帝，两个定义。你说这是法治，还是人治？', NULL),
('gf-02', 'sharp-elder', 'elder-b', 0, 'gf-02-elder-b-l1', '银安殿，王府的正殿。听着挺唬人吧？其实就是和珅家的大客厅。看见那七开间的大气派没？比紫禁城是小多了，但在王爷堆儿里，这是顶配。', NULL),
('gf-02', 'sharp-elder', 'elder-b', 1, 'gf-02-elder-b-l2', '这殿是见客用的，但不是什么客都能进。能进这屋的，起码得是二品往上。和珅坐这儿，来的人先站院子里等，冬天冻得直哆嗦，夏天晒得冒油。他让你等一刻钟，那叫下马威；等半个时辰，说明你得罪他了。', '见客的排场'),
('gf-02', 'sharp-elder', 'elder-b', 2, 'gf-02-elder-b-l3', '和珅有个习惯，见客时手里永远端着一杯茶。那杯茶不是喝的，是卡尺——他跟你说话超过一盏茶的功夫，说明你还算个人物；茶凉了还没续，你就该识趣了。这套茶杯管理学，比现在某些公司的人力资源还精准。', NULL),
('gf-02', 'su-dongpo', 'su-a', 0, 'gf-02-su-a-l1', '这个院子，让我想起当年在汴京宣德楼前等早朝。天没亮，满朝文武缩在袖子里跺脚，跟这院子里等和珅接见的人，怕是同一个表情。', NULL),
('gf-02', 'su-dongpo', 'su-a', 1, 'gf-02-su-a-l2', '我在翰林院时，最烦的就是“等”。等人上朝，等人召见，等皇帝心情好。这个院子里等过多少人？每个人都在心里排练了一百遍要说的话，但真到了跟前，舌头打结。权力的门槛，从来不在脚下，在嗓子眼。', '权力的候诊室'),
('gf-02', 'su-dongpo', 'su-a', 2, 'gf-02-su-a-l3', '有一种说法：清朝的官员，在外地是老虎，进了京是病猫，进了王府门口是蚂蚁。和珅这院子，是蚂蚁排队的地方。我当年被贬出京时，回头看了一眼汴京的城楼，心想：终于不用排队了。那一刻的轻松，比升官还痛快。', NULL),
('gf-02', 'su-dongpo', 'su-b', 0, 'gf-02-su-b-l1', '这个院子，让我想起当年在汴京宣德楼前等早朝。天没亮，满朝文武缩在袖子里跺脚，跟这院子里等和珅接见的人，怕是同一个表情。', NULL),
('gf-02', 'su-dongpo', 'su-b', 1, 'gf-02-su-b-l2', '但你看这院子的布局，方方正正，种的是石榴树——多子多福的意思。和珅把面子功夫做足了，来的客人都觉得自己是自家人。我当年在凤翔做签判，上司也爱用这招：院子修得漂亮，茶泡得好，然后告诉你——今年的考核名额没了。', '和气生财的假面'),
('gf-02', 'su-dongpo', 'su-b', 2, 'gf-02-su-b-l3', '我在黄州时，自己盖了个雪堂，院子只有这儿的十分之一大。但我种了竹子在窗前，来客不用通报，推门就进。因为来的人不是求我办事，是找我喝酒。院子大了，心就远了；院子小了，朋友就近了。和珅这院子，大是大，但他大概一辈子没在自家院子里跟朋友喝醉过。', NULL),
('gf-03', 'sharp-elder', 'elder-a', 0, 'gf-03-elder-a-l1', '到了，这就是传说中的“和珅的保险柜”。这栋后罩楼，上下两层，长一百八十多米。二层那四十四扇窗户——你给我找两扇一样的出来？一扇都没有。每一扇都对应一种宝贝，和珅站在楼下一看窗花，就知道哪个屋放了什么。', NULL),
('gf-03', 'sharp-elder', 'elder-a', 1, 'gf-03-elder-a-l2', '古代没监控没报警器，但和珅有他自己的“物联网系统”——窗花就是他的二维码。那会儿没手机扫码，全靠脑子记。八十六种窗花对应八十六类宝物，金玉珠宝、古玩字画、皮货绸缎，分门别类。这种管理能力，放现在高低是个COO，年薪千万起步。', '防盗的艺术'),
('gf-03', 'sharp-elder', 'elder-a', 2, 'gf-03-elder-a-l3', '这个分类法的厉害之处在于：所有人都知道这楼里有钱，但具体哪个屋放什么，只有和珅和他的心腹知道。抄家的人来了，看着这么多屋子，一个一个翻，跟开盲盒似的。据说足足抄了五天五夜才清理完毕。这叫信息不对称式防盗，放在大数据时代也叫“数据孤岛”。', NULL),
('gf-03', 'sharp-elder', 'elder-b', 0, 'gf-03-elder-b-l1', '到了，这就是传说中的“和珅的保险柜”。这栋后罩楼，上下两层，长一百八十多米。二层那四十四扇窗户——你给我找两扇一样的出来？一扇都没有。每一扇都对应一种宝贝，和珅站在楼下一看窗花，就知道哪个屋放了什么。', NULL),
('gf-03', 'sharp-elder', 'elder-b', 1, 'gf-03-elder-b-l2', '这后罩楼一共108间房。知道为啥108吗？佛教里，108颗念珠，代表108种烦恼。和珅这是把烦恼都锁在屋里了。但讽刺的是——他的烦恼不是没东西，是东西太多了怕被人发现。这是一种什么境界？穷的时候想要有钱，有钱了更睡不着觉。', '108间房的秘密'),
('gf-03', 'sharp-elder', 'elder-b', 2, 'gf-03-elder-b-l3', '抄家时有一条记载特别有意思：打开某间库房，发现整箱的玉如意全发霉了。不是一支两支，是一箱。他收的东西多到自己都忘了。一个人拥有他这辈子根本用不上的东西，这叫什么？这叫仓储式收藏，一种已经超越了使用价值的占有欲。现代人买鞋买包堆一柜子不穿，跟和珅一个毛病——病的名字叫“拥有”。', NULL),
('gf-03', 'su-dongpo', 'su-a', 0, 'gf-03-su-a-l1', '一百零八间房，装尽天下珍宝。可我告诉你，一个人真正需要的，不过是一张床、一方砚、几本书罢了。其余的，都是心上的锁链。', NULL),
('gf-03', 'su-dongpo', 'su-a', 1, 'gf-03-su-a-l2', '和珅搜罗天下珍宝，可他被赐死时，一根绳子了事。东西还在，人没了。我在黄州时全部家当就一个破陶罐，朋友送我一方砚台我就高兴了半年。东西少，搬家方便——我被贬过三次，深知一个道理：你拥有的东西越多，你被拥有的程度就越深。', '物役之悲'),
('gf-03', 'su-dongpo', 'su-a', 2, 'gf-03-su-a-l3', '我曾经写过“长恨此身非我有，何时忘却营营”。写这句词时我刚被贬黄州，在江边看月亮，突然想通了：我前半辈子都在“营营”——追名声、攒俸禄、买好墨好纸。可那些东西哪一样真正属于我？江水千年不变地流，我的俸禄第二年就停了。和珅攒了一辈子的东西，抄家后全归了别人，他只是一个用了一辈子的保管员。', NULL),
('gf-03', 'su-dongpo', 'su-b', 0, 'gf-03-su-b-l1', '一百零八间房，装尽天下珍宝。可我告诉你，一个人真正需要的，不过是一张床、一方砚、几本书罢了。其余的，都是心上的锁链。', NULL),
('gf-03', 'su-dongpo', 'su-b', 1, 'gf-03-su-b-l2', '不过，爱收藏的人，有一种旁人不懂的快乐。我当年在汴京时，也爱到处搜罗字画，看到一张王羲之的拓片，能摸黑起床再看三遍。和珅收集珍宝，未必全为了炫耀——也可能只是停不下来。', '收藏家的痴与劫'),
('gf-03', 'su-dongpo', 'su-b', 2, 'gf-03-su-b-l3', '米芾爱石如命，见了好石头就拜，人称“米颠”。收藏这件事，本来就在痴与疯之间。我有一方砚台，是朋友从端州带来的，我每天亲自洗，比洗脸还认真。后来被贬离家，那方砚台在路上摔成了两半。我心疼了三天，然后拿它继续写字——裂了也能用。和珅要是能悟到这一层，他也许就不会囤八十六间屋子的东西了。', NULL),
('gf-04', 'sharp-elder', 'elder-a', 0, 'gf-04-elder-a-l1', '停，回头看一眼。这道门，是咱中国王府里唯一的欧式门——洛可可风格，汉白玉雕，洋不洋土不土，就这么杵在恭王府后花园的入口。和珅当年造这门，不是崇洋媚外，是嘚瑟：瞧瞧，你们没有的，老子有。', NULL),
('gf-04', 'sharp-elder', 'elder-a', 1, 'gf-04-elder-a-l2', '这门是仿圆明园西洋楼的，圆明园是乾隆爷的，这扇门就是和珅的圆明园。他不能跟皇帝一样建一整片西洋楼，但建一道门过过瘾总可以吧？这道门就是他的“微缩版圆明园”，胆子大得没有边界。', '乾隆的圆明园同款'),
('gf-04', 'sharp-elder', 'elder-a', 2, 'gf-04-elder-a-l3', '乾隆年间，西洋传教士郎世宁、蒋友仁在圆明园搞西洋水法，轰动朝野。和珅看在眼里馋在心里，但圆明园是御园他不能抄，就截取了一个元素——西洋门。你仔细看这门的细节：柱头的茛苕叶纹饰是典型的巴洛克，但门楣上的匾额又是传统中式。这种混搭叫“中体西用”，比洋务运动早了半个多世纪。', NULL),
('gf-04', 'sharp-elder', 'elder-b', 0, 'gf-04-elder-b-l1', '停，回头看一眼。这道门，是咱中国王府里唯一的欧式门——洛可可风格，汉白玉雕，洋不洋土不土，就这么杵在恭王府后花园的入口。和珅当年造这门，不是崇洋媚外，是嘚瑟：瞧瞧，你们没有的，老子有。', NULL),
('gf-04', 'sharp-elder', 'elder-b', 1, 'gf-04-elder-b-l2', '这道门还是个分水岭。前面是府邸——办公社交搞政治；后头是花园——吃喝玩乐搞生活。跨过这道门，和珅就从“和中堂”变成了“和胖子”。官场上的笑容留在门外，进了园子他才能喘口气。', '门内门外的分界线'),
('gf-04', 'sharp-elder', 'elder-b', 2, 'gf-04-elder-b-l3', '据说和珅有个规矩：进了这道门，谁也不许谈公事。天大的事儿在府邸说完，进了花园只能说风月。他在花园里养戏班、修流杯亭、跟文人唱和——装了一辈子孙子，就这一亩三分地能当大爷。但讽刺的是，最后扳倒他的那些罪状，全是他在“公事区”干的事。这道门没护住他。', NULL),
('gf-04', 'su-dongpo', 'su-a', 0, 'gf-04-su-a-l1', '这道门有意思。推开它，就从公务走进了私心。我在杭州修苏堤时，也曾想修这样一道门——一边是太守的职责，一边是诗人的自由。可惜我的门是虚的，和珅把它做实了。', NULL),
('gf-04', 'su-dongpo', 'su-a', 1, 'gf-04-su-a-l2', '宋人最怕“华夷之辨”，但你看这西洋风格的雕刻，和珅倒是很放得开。我当年在惠州，跟一个波斯商人学酿葡萄酒，同僚弹劾我“有失官体”。中国人总觉得学洋人的东西就是丢人，这个毛病到现在也没好透。', '中西合璧的胸怀'),
('gf-04', 'su-dongpo', 'su-a', 2, 'gf-04-su-a-l3', '我在海南儋州时，跟黎族同胞学用槟榔染布，穿着五颜六色的衣服在街上走。当地官员看见了，上书说我“行为怪诞有辱斯文”。我就纳了闷了——好看的东西，分什么华夷？和珅敢在自家门口立一道西洋门，至少说明他的审美没被“祖制”二字框死。他的错不在洋为中用，在贪得无厌。', NULL),
('gf-04', 'su-dongpo', 'su-b', 0, 'gf-04-su-b-l1', '这道门有意思。推开它，就从公务走进了私心。我在杭州修苏堤时，也曾想修这样一道门——一边是太守的职责，一边是诗人的自由。可惜我的门是虚的，和珅把它做实了。', NULL),
('gf-04', 'su-dongpo', 'su-b', 1, 'gf-04-su-b-l2', '但门这东西，从来挡不住什么。和珅把公务和私心分得清，以为一道门就能隔开两种人生。可皇上不管这些，抄家时前院后园一起端。我当年被抄家，最可惜的不是值钱的东西，是那些写了半截的诗稿。', '门是心之界'),
('gf-04', 'su-dongpo', 'su-b', 2, 'gf-04-su-b-l3', '诗稿不值钱，但那是我跟自己的对话。和珅的门，挡得住官场的窥探，挡不住命运的清算。我写过“人生如逆旅，我亦是行人”——行人是没有固定住处的，自然也无需用门来分割什么。门内门外的执念，只有把这院子当成自己的人才会有。而我，早就不当自己是院子的主人了。', NULL),
('gf-05', 'sharp-elder', 'elder-a', 0, 'gf-05-elder-a-l1', '看见这池子没？形状像只蝙蝠，所以叫“蝠池”。蝠，福。中国人玩谐音梗，和珅是鼻祖。他把整个花园都设计成了“万福园”——据说园子里里外外藏了一万只蝙蝠图案。这不是花园，是一个大型祈福现场。', NULL),
('gf-05', 'sharp-elder', 'elder-a', 1, 'gf-05-elder-a-l2', '一万只蝙蝠什么概念？这园子里，窗棂上、门扇上、回廊上、假山石刻上，全是蝙蝠。明的暗的都有。和珅是恨不得在空气里都画蝙蝠。一个人这么疯狂地求福，你觉得是为什么？因为他知道自己干的事，福报不太够。', '一万只蝙蝠的执念'),
('gf-05', 'sharp-elder', 'elder-a', 2, 'gf-05-elder-a-l3', '民间说法，恭王府花园里共有9999只蝙蝠图案，加上那个著名的康熙御笔“福”字碑，正好凑成一万。但9999这个数字，离“万”只差一，象征“万福不到头”，永远在追。这是一种极聪明的设计——不把话说满，不把路走死。但和珅自己没做到，他把路走得死死的。讽刺吗？他设计的园子教他做人，他没听。', NULL),
('gf-05', 'sharp-elder', 'elder-b', 0, 'gf-05-elder-b-l1', '看见这池子没？形状像只蝙蝠，所以叫“蝠池”。蝠，福。中国人玩谐音梗，和珅是鼻祖。他把整个花园都设计成了“万福园”——据说园子里里外外藏了一万只蝙蝠图案。这不是花园，是一个大型祈福现场。', NULL),
('gf-05', 'sharp-elder', 'elder-b', 1, 'gf-05-elder-b-l2', '再说这池子本身。蝠池周围种的全是榆树，春天榆钱飘下来落进池水里，水面一片铜钱形状。和珅站在池边往下看，看见的是一池子的钱。这种沉浸式炫富，比脖子上挂大金链子高级太多了。', '这池子也讲究'),
('gf-05', 'sharp-elder', 'elder-b', 2, 'gf-05-elder-b-l3', '榆树还有一个妙用：榆钱谐音“余钱”。和珅在这个池子边招待客人时，总是不经意地让人看见榆钱漂满水面。客人心里明白——这是在暗示“我府上处处是余钱”。但他嘴上从不说。真正的炫耀是让别人自己得出结论，最高级的凡尔赛是让景物替你开口。', NULL),
('gf-05', 'su-dongpo', 'su-a', 0, 'gf-05-su-a-l1', '蝠池，蝠即福。和珅在园子里藏了一万只蝙蝠，想把福气钉死在自家墙上。可福气这东西，你越关着它，它越要飞。我的经验是：福气跟蝴蝶一样，你追它就跑，你坐在树下做自己的事，它就落你肩上了。', NULL),
('gf-05', 'su-dongpo', 'su-a', 1, 'gf-05-su-a-l2', '宋朝人也信这个。我画竹子，旁边常加一块石头，叫“祝石”——祝，竹的谐音。但我们点到为止，不像和珅这样搞一万只。他这不是祈福，是攒福，把福当银子一样存起来。可心不安，攒多少福都压不住。', '谐音梗的前世今生'),
('gf-05', 'su-dongpo', 'su-a', 2, 'gf-05-su-a-l3', '我在黄州种地时，屋后有一棵老槐树，当地人说“槐”通“财”。我就在树下搭了个石桌，朋友来了坐着喝茶。那棵槐树陪了我四年，我从没觉得它给我带了什么财，但它给我的阴凉是真的。福这东西，得是真的才管用。和珅的9999只蝙蝠全是假的，没一只会飞。', NULL),
('gf-05', 'su-dongpo', 'su-b', 0, 'gf-05-su-b-l1', '蝠池，蝠即福。和珅在园子里藏了一万只蝙蝠，想把福气钉死在自家墙上。可福气这东西，你越关着它，它越要飞。我的经验是：福气跟蝴蝶一样，你追它就跑，你坐在树下做自己的事，它就落你肩上了。', NULL),
('gf-05', 'su-dongpo', 'su-b', 1, 'gf-05-su-b-l2', '一个人求福求到这个份上，说明心里有多大的窟窿啊。和珅知道自己弹劾他的人多，知道自己得罪的人多，所以拼命用吉祥符号把自己包起来——像个穿了一百件防弹衣的人，但真正致命的不是子弹，是暗算。', '贪心与不安'),
('gf-05', 'su-dongpo', 'su-b', 2, 'gf-05-su-b-l3', '我在官场上跌过大跟头，被关过御史台，那地方又叫“乌台”。黑漆漆的牢房里只有一扇巴掌大的窗。我在墙上看到以前犯人刻的痕迹，有人刻了个“福”字，歪歪扭扭。那一刻我明白了：人最想求福的时候，往往是他离福最远的时候。和珅的万蝠园，本质上跟那个囚犯的刻字一样——都是恐惧的产物。', NULL),
('gf-06', 'sharp-elder', 'elder-a', 0, 'gf-06-elder-a-l1', '流杯亭，王羲之《兰亭序》里的曲水流觞。把酒杯放水面上，流到谁跟前谁作诗，作不出来罚酒三杯——这是古代文人的高端轰趴。和珅附庸风雅，在自家花园也搞了一个。但说实话，他那些诗，放现在连朋友圈都发不出去。', NULL),
('gf-06', 'sharp-elder', 'elder-a', 1, 'gf-06-elder-a-l2', '和珅这辈子最大的执念不是钱，是被当成文化人。他有钱有权，但朝中那些进士翰林背地里还是看不起他——他出身侍卫，没功名。所以他到处学文人雅士，修流杯亭、请诗人来聚会。但这玩意儿学不来，你闻闻这亭子的味儿，有墨香吗？没有，只有铜臭。', '抄袭兰亭'),
('gf-06', 'sharp-elder', 'elder-a', 2, 'gf-06-elder-a-l3', '和珅为了弥补出身的自卑，下了很大功夫。他练字，摹赵孟頫，工工整整；他背诗，能背几百首唐诗；他请袁枚来府上吃饭，袁枚是当时文人圈的头号红人。袁枚来了，吃完写了首诗夸他，和珅高兴得差点管袁枚叫爸爸。但该看不起他的人还是看不起他。文化圈的鄙视链，比官场的还顽固。', NULL),
('gf-06', 'sharp-elder', 'elder-b', 0, 'gf-06-elder-b-l1', '流杯亭，王羲之《兰亭序》里的曲水流觞。把酒杯放水面上，流到谁跟前谁作诗，作不出来罚酒三杯——这是古代文人的高端轰趴。和珅附庸风雅，在自家花园也搞了一个。但说实话，他那些诗，放现在连朋友圈都发不出去。', NULL),
('gf-06', 'sharp-elder', 'elder-b', 1, 'gf-06-elder-b-l2', '我告诉你王羲之那场聚会的真相：一群老爷们喝多了，在兰亭的地上歪着躺着，衣服湿了不管，写的诗有好有烂。烂的也没人笑话，因为都是朋友。和珅这流杯亭，来的全是马屁精，杯子还没流到他面前，诗已经写好揣袖子里了。', '真正的曲水流觞什么样'),
('gf-06', 'sharp-elder', 'elder-b', 2, 'gf-06-elder-b-l3', '永和九年那场雅集，王羲之喝醉了才写出《兰亭序》——醒来后再写几遍，发现没有醉时写得好。好的东西是松弛的产物，不是排练的产物。和珅的雅集，排练得比春晚还齐整。据说有一次一个客人故意吟了句烂诗试探他，和珅当场脸就垮了。真正的雅，是经得起烂的。装出来的雅，处处是破绽。', NULL),
('gf-06', 'su-dongpo', 'su-a', 0, 'gf-06-su-a-l1', '曲水流觞！这是我在黄州时做梦都想搞的东西。可惜那会儿穷，挖不起水渠，就用竹子劈成两半接水代替，倒也痛快。和珅这亭子挖得讲究，但我打赌，他从没真正喝醉过。', NULL),
('gf-06', 'su-dongpo', 'su-a', 1, 'gf-06-su-a-l2', '真正的曲水流觞，不在水也不在杯，在醉。微醺之后，大家不再端着，诗才从心里往外冒。我在黄州和几个朋友凑了六个人，酒是散装的劣酒，杯子是缺口的陶杯，但我们写的诗比我在翰林院应制时好一百倍——因为那些诗不是写给皇上看的，是写给彼此看的。', '醉的真假'),
('gf-06', 'su-dongpo', 'su-a', 2, 'gf-06-su-a-l3', '那次黄州雅集，酒杯卡在石头缝里不动了，我们说这是天意——卡杯的人喝双倍。结果那天卡了三次，被罚的那个人后来趴在我肩头哭，说被贬三年今天最高兴。和珅的流杯亭，水流的角度是经过计算的，杯子永远不会卡住。太顺畅了，反而没意思。人生的味道，往往在于那点“卡住”。', NULL),
('gf-06', 'su-dongpo', 'su-b', 0, 'gf-06-su-b-l1', '曲水流觞！这是我在黄州时做梦都想搞的东西。可惜那会儿穷，挖不起水渠，就用竹子劈成两半接水代替，倒也痛快。和珅这亭子挖得讲究，但我打赌，他从没真正喝醉过。', NULL),
('gf-06', 'su-dongpo', 'su-b', 1, 'gf-06-su-b-l2', '但我也不全否定和珅。一个人哪怕附庸风雅，也比只认钱的人强半截。他至少知道什么是好的，只是够不着。我见过太多人连够都不想够，和珅至少还伸了手。', '雅趣的真伪'),
('gf-06', 'su-dongpo', 'su-b', 2, 'gf-06-su-b-l3', '我在凤翔做官时，手下一个文书每天抄公文，字写得像印刷体。有一天我发现他在废纸上摹我的字，摹得不像但很认真。我问他喜欢吗，他说他不懂就是觉得好看。我当场送了他一幅字，他激动得额头冒汗。附庸风雅的人不可耻，他们只是站在美的大门外面往里看。和珅的问题不是他不配风雅，是他太想让人知道他风雅了。真正的风雅，不需要观众。', NULL),
('gf-07', 'sharp-elder', 'elder-a', 0, 'gf-07-elder-a-l1', '到了，全园最值钱的玩意儿——康熙御笔“福”字碑。康熙这辈子极少题字，这个福字是他给孝庄太后写的，后来不知怎么就跑到和珅手里了。这碑立的地方也有讲究，在一条石龙的正下方——这是龙口衔福。就这么跟你说吧，这园子里一万只蝙蝠全是虚的，这个碑才是真福，和珅的命根子。', NULL),
('gf-07', 'sharp-elder', 'elder-a', 1, 'gf-07-elder-a-l2', '这碑藏在假山底下的秘云洞里，为什么？不是怕人偷，是谁偷了都没用。和珅设计这个位置，恰好在北京城中轴线的龙脉上。他这宅子本就压在龙脉的边上，而这福字碑正好点在那条脉的穴位上。风水学上的说法是：得了龙脉的福气，江山都压不住。', '福字为什么被藏在这儿'),
('gf-07', 'sharp-elder', 'elder-a', 2, 'gf-07-elder-a-l3', '据说抄家时有人建议把福字碑搬回皇宫，但嘉庆犹豫再三，最后没动。一是因为碑在假山底下，要取就得把整座假山拆了——拆假山等于动龙脉，怕不吉利；二是有说法，这碑已经和龙脉连在一起，动碑就是动国本。和珅生前最大的算计，不是贪，是用风水把皇帝逼到了两难的境地。你可以抄我的家，但你不能动国家的风水。他赢了这最后一局。', NULL),
('gf-07', 'sharp-elder', 'elder-b', 0, 'gf-07-elder-b-l1', '到了，全园最值钱的玩意儿——康熙御笔“福”字碑。康熙这辈子极少题字，这个福字是他给孝庄太后写的，后来不知怎么就跑到和珅手里了。这碑立的地方也有讲究，在一条石龙的正下方——这是龙口衔福。就这么跟你说吧，这园子里一万只蝙蝠全是虚的，这个碑才是真福，和珅的命根子。', NULL),
('gf-07', 'sharp-elder', 'elder-b', 1, 'gf-07-elder-b-l2', '你看这个“福”字，一个字藏了五个字：多、子、才、寿、福。左边像“才”，右上角是“多”，右下角是“田”（过去田就是福），整体你细品，“寿”字的影子也在里面。一个字五合一，比打包赠品还划算。现在的人拍照只拍石碑正面，但真正牛的是这个字的写法本身。', '康熙的这个福字有多绝'),
('gf-07', 'sharp-elder', 'elder-b', 2, 'gf-07-elder-b-l3', '康熙的字是董其昌一脉，清秀有力。但他平时极少题字，尤其是单写一个“福”字的，整个中国就这一个。这是他写给孝庄的，孝庄当时病重，康熙以天子之笔写福为祖母续寿。这个福字，先有孝心，再有政治寓意，最后才被和珅拿去当成了护身符。一个人的孝心，变成另一个人的贪心——文物的命运，有时候比小说还曲折。', NULL),
('gf-07', 'su-dongpo', 'su-a', 0, 'gf-07-su-a-l1', '康熙的福字，和珅当命根子藏着。可笑。我告诉你，真正的福不是刻在石头上让万人摸的，是你深夜里觉得今天过得踏实。', NULL),
('gf-07', 'su-dongpo', 'su-a', 1, 'gf-07-su-a-l2', '我在惠州时，当地人说罗浮山上有块仙石，摸了能长寿。我爬上去一看，那石头早被人摸得油光水滑。我没摸，在山顶看了会儿云海就下来了。第二年那些摸石头的人该怎么病还怎么病。和珅把这个福字藏在洞里当镇宅之宝，但他就没想明白——刻在石头上的叫字，活在心里的才叫福。', '福不在石'),
('gf-07', 'su-dongpo', 'su-a', 2, 'gf-07-su-a-l3', '福字碑现在成了恭王府最火的景点，所有人排队进去摸一把，摸完还要拍照。如果康熙知道他给祖母写的这个福字，最后被几百万人手汗侵蚀，估计会后悔当年动了笔。和珅更不会想到，他藏的宝贝变成了打卡点。这大概就是“福”的真正含义——你永远控制不了它的流向。和珅想独吞，结果全民共享。', NULL),
('gf-07', 'su-dongpo', 'su-b', 0, 'gf-07-su-b-l1', '康熙的福字，和珅当命根子藏着。可笑。我告诉你，真正的福不是刻在石头上让万人摸的，是你深夜里觉得今天过得踏实。', NULL),
('gf-07', 'su-dongpo', 'su-b', 1, 'gf-07-su-b-l2', '刚才排队进洞时我注意到，每个人摸这碑的手法都不一样。有求财的用手心拍，想儿子的摸那个“子”字，求长寿的在“寿”字上反复蹭。一块碑，被摸出了几十种心愿。和珅若泉下有知，大概会笑：福气是分着用才灵的，他当年不懂这个道理。', '摸福的众生相'),
('gf-07', 'su-dongpo', 'su-b', 2, 'gf-07-su-b-l3', '我一生去过很多庙，从来不烧香，但会站在香炉边看人烧。有的求中举，有的求病愈，有的求添丁。香火升起的那一刻，所有人脸上都写着一样的表情：希望。这福字碑和香炉是同一回事——重要的不是有没有用，是那一刻人心里有了光。和珅以为他藏住的是福，其实他锁住的只是石头。真正的福，在进进出出摸石头的那些普通人的心愿里。', NULL),
('gf-08', 'sharp-elder', 'elder-a', 0, 'gf-08-elder-a-l1', '看见对面那座大戏楼没？中国现存最大的室内戏楼，号称“不出府门听大戏”。和珅把名角儿请到家里来唱，有时候自己也上台嚎两嗓子。据说他唱得很难听，但客人们巴掌都拍红了。', NULL),
('gf-08', 'sharp-elder', 'elder-a', 1, 'gf-08-elder-a-l2', '这戏楼修得大有文章。上下三层，地底下还有一口深井——不是打水的，是扩音用的。演员在台上唱，声音通过井水共振传到最后一排，天然音响，不用电。和珅对声学的研究，要是用在科举上，可能真能考上功名。', '唱戏的是疯子，听戏的是傻子'),
('gf-08', 'sharp-elder', 'elder-a', 2, 'gf-08-elder-a-l3', '这种声学设计叫“地瓮扩音”，原理跟你在浴室唱歌一个道理——瓷砖硬表面反射声波，混响效果好。这口井深六米，直达地下水层，声波下去再弹上来，形成自然环绕立体声。和珅请的工匠里肯定有懂声学的行家。只是这技术用在了享乐上，没用在正途上，算是古代科技的娱乐化应用。', NULL),
('gf-08', 'sharp-elder', 'elder-b', 0, 'gf-08-elder-b-l1', '看见对面那座大戏楼没？中国现存最大的室内戏楼，号称“不出府门听大戏”。和珅把名角儿请到家里来唱，有时候自己也上台嚎两嗓子。据说他唱得很难听，但客人们巴掌都拍红了。', NULL),
('gf-08', 'sharp-elder', 'elder-b', 1, 'gf-08-elder-b-l2', '乾隆来过不止一次。皇上出宫来臣子家听戏，这是天大的面子。但这也是和珅倒台的原因之一——你让皇上觉得你比他还会享受，这不是找死吗？和珅家的戏台比宫里漱芳斋还大，这是僭越，是罪状里最重的一条。', '谁在他家听过戏'),
('gf-08', 'sharp-elder', 'elder-b', 2, 'gf-08-elder-b-l3', '乾隆八十多岁时最后一次来恭王府听戏，和珅亲自给乾隆捧茶。据说那天唱的是一出《长生殿》，讲杨贵妃和唐明皇。乾隆听了一半突然离席，没人知道他为什么走。后来有人揣测：乾隆在那出戏里看到了自己——年迈的帝王，身边是权臣而非忠臣。戏散了，和珅的命运也快散场了。', NULL),
('gf-08', 'su-dongpo', 'su-a', 0, 'gf-08-su-a-l1', '戏楼，我熟。我在杭州当通判时，最爱上元夜溜去勾栏瓦舍看杂剧，被同僚撞见过一回，弹劾我“有辱官箴”。我心想，官箴里又没写不能看戏。和珅比我会做人——他直接把戏台搬回自己家，谁也弹劾不了他。', NULL),
('gf-08', 'su-dongpo', 'su-a', 1, 'gf-08-su-a-l2', '这戏台上演过多少悲欢离合，但真正的大戏不在台上，在这园子本身。和珅从权倾朝野到白绫赐死，奕䜣从皇位候选人到恭亲王再到晚年凄凉——这宅子换了三个主角，比戏台上任何一出都精彩。', '人生如戏的真意'),
('gf-08', 'su-dongpo', 'su-a', 2, 'gf-08-su-a-l3', '我写过“人生到处知何似，应似飞鸿踏雪泥”。和珅在这园子里煞费苦心留痕，想把每一个脚印都刻进石头里。可是雪一化，什么都没了。恭王府现在叫“恭”王府，鬼知道再过一百年它叫谁家的府。台上的人来来去去，只有台下的石头是永恒的观众。', NULL),
('gf-08', 'su-dongpo', 'su-b', 0, 'gf-08-su-b-l1', '戏楼，我熟。我在杭州当通判时，最爱上元夜溜去勾栏瓦舍看杂剧，被同僚撞见过一回，弹劾我“有辱官箴”。我心想，官箴里又没写不能看戏。和珅比我会做人——他直接把戏台搬回自己家，谁也弹劾不了他。', NULL),
('gf-08', 'su-dongpo', 'su-b', 1, 'gf-08-su-b-l2', '不过我很羡慕后世戏曲的繁荣。宋朝还没京剧，我们看的是参军戏、傀儡戏，简单得很。清朝的徽班进京，融合各地声腔，最后在这里、在这样的大戏楼上锤炼成了京剧。和珅不知道，他养戏班子的爱好，客观上为中国戏曲贡献了一座顶级排练厅。', '戏曲里的中国'),
('gf-08', 'su-dongpo', 'su-b', 2, 'gf-08-su-b-l3', '乾隆五十五年，徽班进京，那是中国戏曲史上的大事件。和珅作为权臣，少不了推波助澜。他请的戏班子里，说不定就有当年徽班的名角。一个人在历史上的作用，往往和他本人的主观意图无关。和珅只是想听好戏，结果客观上成了京剧诞生期的赞助人。善恶由人评说，功过却常常在当事人的视线之外——这是历史最狡猾的地方。', NULL),
('gf-09', 'sharp-elder', 'elder-a', 0, 'gf-09-elder-a-l1', '妙香亭，名字起得跟香水广告似的。这亭子是奕䜣后来加的，和珅当年不在这儿——他那会儿这儿是一堆假山。但你知道吗，亭子建在这儿是为了纪念一个女人。', NULL),
('gf-09', 'sharp-elder', 'elder-a', 1, 'gf-09-elder-a-l2', '奕䜣的福晋，瓜尔佳氏，在这园子里住了一辈子。她死后奕䜣在这儿建了这个亭子，取佛教里“妙香”二字，“妙香佛国”是香积如来的净土。一个搞洋务运动的大老爷们，私底下在这儿偷偷想老婆。你看这亭子的朝向，正好对着西边——佛教里西方是极乐世界。', '恭亲王的白月光'),
('gf-09', 'sharp-elder', 'elder-a', 2, 'gf-09-elder-a-l3', '奕䜣和福晋感情极好，福晋去世后他写了大量悼亡诗。其中有一句“卅载画眉人已去”，意思是给我画了三十年眉毛的人走了。那个在朝堂上跟慈禧斗智斗勇的恭亲王，在这亭子里不过是个想老婆的老头。所以别被历史人物标签骗了，恭亲王这个庙号虽然刻在历史上，但妙香亭刻的是他心上的纹路。', NULL),
('gf-09', 'sharp-elder', 'elder-b', 0, 'gf-09-elder-b-l1', '妙香亭，名字起得跟香水广告似的。这亭子是奕䜣后来加的，和珅当年不在这儿——他那会儿这儿是一堆假山。但你知道吗，亭子建在这儿是为了纪念一个女人。', NULL),
('gf-09', 'sharp-elder', 'elder-b', 1, 'gf-09-elder-b-l2', '有趣的是，和珅的园子，奕䜣住进来后改了不少。和珅喜欢奢华，奕䜣有节制。这座亭子放在和珅时代是不可能的——太素净，赚不了面子。但奕䜣后半辈子经历太多，反而觉得素净挺好。', '和珅和奕䜣的隔空对望'),
('gf-09', 'sharp-elder', 'elder-b', 2, 'gf-09-elder-b-l3', '奕䜣晚年信佛，这亭子东侧就是他修的佛堂。权力斗争累了，就过来对着亭子念念经。和珅的园子是给外人看的，奕䜣改了之后，这园子才开始有内向的一面。一个是向外扩张的贪，一个是向内收敛的倦。同一个园子，两代主人两种心境。所以这园林跟人一样，气质是住出来的。', NULL),
('gf-09', 'su-dongpo', 'su-a', 0, 'gf-09-su-a-l1', '一座亭子，为一个女子而建。恭亲王比他爹道光有福气，至少有个值得建亭子的人。我也有过这样一个人——我的夫人王弗，死后我种了三万棵松树在她墓旁。建亭子也好，种松树也好，都是一种很笨的挽留。活着的时候没觉得，人不在了，才想把风景都刻上她的名字。', NULL),
('gf-09', 'su-dongpo', 'su-a', 1, 'gf-09-su-a-l2', '“十年生死两茫茫，不思量，自难忘。”这是王弗死后十年写的。王弗十六岁嫁我，二十七岁去世。她活着的时候我总觉得日子还长，后来才知道，日子经不起数。奕䜣建这亭子时大概也差不多——他在朝堂跟慈禧周旋了半辈子，最后发现最安宁的回忆全是和福晋在园子里的日常。', '悼亡这件事'),
('gf-09', 'su-dongpo', 'su-a', 2, 'gf-09-su-a-l3', '王弗有一个习惯，我在外头见客，她躲在屏风后面听。人走了，她告诉我这人靠得住、那人话里有话。我起初嫌她多事，后来她走了，我吃了多少次亏才明白她在替我挡箭。恭亲王身边大概也有这样一双眼睛，在的时候是日常，没了才知是守护。亭子再好看，也比不上那个人能再多看你一眼。', NULL),
('gf-09', 'su-dongpo', 'su-b', 0, 'gf-09-su-b-l1', '一座亭子，为一个女子而建。恭亲王比他爹道光有福气，至少有个值得建亭子的人。我也有过这样一个人——我的夫人王弗，死后我种了三万棵松树在她墓旁。建亭子也好，种松树也好，都是一种很笨的挽留。活着的时候没觉得，人不在了，才想把风景都刻上她的名字。', NULL),
('gf-09', 'su-dongpo', 'su-b', 1, 'gf-09-su-b-l2', '我在徐州也建过一座亭子，叫放鹤亭。但我那是给鹤建的，奕䜣这是给人建的。一个人愿意在花园里给亡妻留个位置，说明这花园不再只是显摆的场所，它开始有心了。和珅的园子没有这种东西，那是一个展示厅；奕䜣给它装了心脏。', '园林的深情'),
('gf-09', 'su-dongpo', 'su-b', 2, 'gf-09-su-b-l3', '园林跟人一样，年轻时比排场，老了比深情。我在黄州雪堂种竹子时，旁边特意留了块空地，想着哪天王弗能来看——明知不可能，但种的时候手停不下来。奕䜣建妙香亭的念头，大概也是某天夜里突然冒出来的：这里应该有个亭子，让她坐一坐。园林最值钱的，不是奇石异木，是某棵树下埋着的那个念头。', NULL),
('gf-10', 'sharp-elder', 'elder-a', 0, 'gf-10-elder-a-l1', '逛完了，感觉怎么样？一座恭王府，半部清朝史，这话真不是吹的。你想想，和珅在这园子里风光了二十年，换来的是一根白绫；奕䜣在这儿住了大半辈子，眼瞅着大清一天天往下出溜。如今他俩都不在了，你跟我在这儿溜达了一下午。这就叫风水轮流转，转到最后，只有游客。', NULL),
('gf-10', 'sharp-elder', 'elder-a', 1, 'gf-10-elder-a-l2', '和珅这人吧，你说他贪，他确实贪了三千个亿；可你说他蠢，他能说五种语言，帮乾隆处理了无数烂摊子。乾隆晚年那些奏折，不是乾隆批的，是和珅代批的。一个能干的人贪起来，比蠢人可怕一百倍。嘉庆杀他是对的，但杀完之后发现——活儿没人干了。这就是大清朝的困局。', '和珅到底是个什么人'),
('gf-10', 'sharp-elder', 'elder-a', 2, 'gf-10-elder-a-l3', '史学家有个说法：和珅跌倒，嘉庆吃饱。但吃饱之后呢？继任的大臣没一个能和珅比行政效率。他把持朝政几十年，不只是靠巴结，是有真本事的。他懂财政、通语言、会办案，乾隆六下江南的烂账全是他平的。他倒台后，清政府的财政体系迅速恶化，不到二十年就出了道光年间的白银危机。杀一个贪官容易，建立一个不贪的高效体系，清朝从没做到。', NULL),
('gf-10', 'sharp-elder', 'elder-b', 0, 'gf-10-elder-b-l1', '逛完了，感觉怎么样？一座恭王府，半部清朝史，这话真不是吹的。你想想，和珅在这园子里风光了二十年，换来的是一根白绫；奕䜣在这儿住了大半辈子，眼瞅着大清一天天往下出溜。如今他俩都不在了，你跟我在这儿溜达了一下午。这就叫风水轮流转，转到最后，只有游客。', NULL),
('gf-10', 'sharp-elder', 'elder-b', 1, 'gf-10-elder-b-l2', '这园子后来命运也不怎么样。奕䜣死后几经转手，民国时成了辅仁大学的校舍，后来又变成大杂院。据说上世纪八十年代，里头住了一百多户人家，院子里全搭着蜂窝煤棚子，走廊里摆着煤气灶。和珅要是知道他那蝠池曾经有人在旁边洗尿布，估计直接从地底下蹦起来。', '这园子的命运'),
('gf-10', 'sharp-elder', 'elder-b', 2, 'gf-10-elder-b-l3', '2008年恭王府才全面开放。在此之前的一百多年里，它当过王府、当过教会学校、当过民居大院。一座园子，比一个国家的制度还长寿。它看过清朝的末日、民国的乱局、新中国的变迁。和珅费尽心思想让福气永远留在自己手里，但真正的赢家是他脚下的这块地。地不会说话，但地比谁都有耐心。', NULL),
('gf-10', 'su-dongpo', 'su-a', 0, 'gf-10-su-a-l1', '逛完了。我陪了你一路，现在问你一句：这满园的亭台楼阁，你觉得哪一处最好？我猜不是银安殿，不是福字碑，可能是某条你一个人站着发了会儿呆的小径。风景是属于所有人的，但那一刻只属于你。', NULL),
('gf-10', 'su-dongpo', 'su-a', 1, 'gf-10-su-a-l2', '我一生住过很多地方——汴京、杭州、黄州、惠州、儋州。每一个地方我走的时候都觉得是最后一次看它。可后来回头看，没有哪一片风景真正属于我，也没有哪一片风景真正抛弃我。和珅把这园子攥得太紧，反而成了心魔；奕䜣看淡了，但这园子的修缮工程累垮了他的身体。不松不紧，才是智慧。', '院子与过客'),
('gf-10', 'su-dongpo', 'su-a', 2, 'gf-10-su-a-l3', '我在儋州住了三年，临走时在墙上写了一首诗，最后两句是：“他年谁作舆地志，海南万里真吾乡。”意思是：将来有人编地理志，会说海南才是我的故乡。我一个四川人，把海南当故乡——不是四川不好，是漂泊久了就懂了，故乡不是一个地理坐标，是你心安的地方。这恭王府对和珅来说是命根子，对奕䜣来说是负担，对你来说——只是一下午的散步。这就很好。', NULL),
('gf-10', 'su-dongpo', 'su-b', 0, 'gf-10-su-b-l1', '逛完了。我陪了你一路，现在问你一句：这满园的亭台楼阁，你觉得哪一处最好？我猜不是银安殿，不是福字碑，可能是某条你一个人站着发了会儿呆的小径。风景是属于所有人的，但那一刻只属于你。', NULL),
('gf-10', 'su-dongpo', 'su-b', 1, 'gf-10-su-b-l2', '你大老远跑来，花钱买票，在人堆里挤一下午，到底图什么？不是图学到什么知识——那些百度上都有。你图的，可能是站在某个角落时，突然觉得这石头这树，跟你有过一秒钟的默契。我做了一辈子旅行者，可以负责任地告诉你：那一秒钟，就是全部意义。', '旅行的意义'),
('gf-10', 'su-dongpo', 'su-b', 2, 'gf-10-su-b-l3', '我在赤壁写“大江东去”时，也没搞清楚赤壁之战到底发生在哪儿——搞错了，我去的不是真赤壁，是个假赤壁。但那又怎样呢？江是真的，风是真的，我站在那儿的感觉是真的。后来有学者专门写文章考证我的错误，我若泉下有知，只想回他一句：你不懂旅行。旅行不是考证，是你和风景之间那一点私密的默契。今天在这恭王府，但愿你也有一秒钟那样的时刻。', NULL);
